const SANITY_API_TOKEN = 'REPLACED_SANITY_TOKEN';
const SANITY_PROJECT_ID = 'r6ztl1oq';
const SANITY_DATASET = 'production';

async function createPost(post) {
  const url = `https://${SANITY_PROJECT_ID}.api.sanity.io/v2024-01-01/data/mutate/${SANITY_DATASET}?returnIds=true`;
  const body = JSON.stringify({ mutations: [{ create: { _type: 'post', ...post } }] });
  const resp = await fetch(url, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${SANITY_API_TOKEN}` },
    body
  });
  const data = await resp.json();
  if (data.results && data.results[0]) return data.results[0].id;
  throw new Error(JSON.stringify(data));
}

