const allPosts = [post25, post26, post27, post28, post29, post30, post31, post32, post33, post34, post35, post36, post37, post38];

async function main() {
  console.log(`Creating ${allPosts.length} blog posts...\n`);
  let ok = 0, fail = 0;
  for (let i = 0; i < allPosts.length; i++) {
    const post = allPosts[i];
    const num = 25 + i;
    try {
      const id = await createPost(post);
      console.log(`[#${num}] OK: ${post.title.en} -> ${id}`);
      ok++;
    } catch (e) {
      console.error(`[#${num}] FAIL: ${post.title.en} -> ${e.message}`);
      fail++;
    }
  }
  console.log(`\nDone: ${ok} created, ${fail} failed out of ${allPosts.length}`);
}

main();